def count_vowels(s):
    count = 0
    for ch in s:
        if ch.lower() in 'aeiou':
            count += 1
    return count

def second_largest(nums):
    distinct = set(nums)
    if len(distinct) < 2:
        raise ValueError("List must contain at least two distinct numbers")
    distinct.remove(max(distinct))
    return max(distinct)

def roman_to_int(s):
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman[s[i]] < roman[s[i + 1]]:
            total += roman[s[i + 1]] - roman[s[i]]
            i += 2
        else:
            total += roman[s[i]]
            i += 1
    return total

def is_anagram(a, b):
    import collections
    def normalize(s):
        return [ch.lower() for ch in s if not ch.isspace()]
    return collections.Counter(normalize(a)) == collections.Counter(normalize(b)))

def flatten(nested):
    result = []
    for elem in nested:
        if isinstance(elem, list):
            result.extend(flatten(elem))
        else:
            result.append(elem)
    return result

import re
from collections import Counter

def word_frequencies(text):
    words = re.findall(r'\b\w+\b', text.lower())
    return dict(Counter(words))

def run_length_encode(s):
    if not s:
        return ''
    result = []
    count = 1
    prev = s[0]
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = ch
            count = 1
    result.append(prev + str(count))
    return ''.join(result)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def median(nums):
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return sorted_nums[mid]
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2
